// Validate incoming approval request
const body = $input.first().json.body;

const required = ['post_id', 'decision'];
const missing = required.filter(f => !body[f]);
if (missing.length > 0) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

const validDecisions = ['approved', 'rejected', 'edited'];
if (!validDecisions.includes(body.decision)) {
  throw new Error(`Invalid decision: ${body.decision}. Must be one of: ${validDecisions.join(', ')}`);
}

if (body.decision === 'edited' && !body.content) {
  throw new Error('Edited decision requires content field with updated post text');
}

return [{
  json: {
    post_id: body.post_id,
    decision: body.decision,
    content: body.content || null,
    rejection_reason: body.rejection_reason || null,
    scheduled_for: body.scheduled_for || null
  }
}];

// Merge post data with approval decision
const postData = $input.first().json;
const approvalData = $('Validate Approval Request').item.json;

if (!postData.id) {
  throw new Error(`Post not found: ${approvalData.post_id}`);
}

if (postData.post_status === 'published') {
  throw new Error(`Post ${postData.id} is already published`);
}
if (postData.approval_status === 'approved' && approvalData.decision === 'approved') {
  throw new Error(`Post ${postData.id} is already approved`);
}

const finalContent = (approvalData.decision === 'edited' && approvalData.content)
  ? approvalData.content
  : postData.content;

const finalDecision = approvalData.decision === 'edited' ? 'approved' : approvalData.decision;

return [{
  json: {
    post_id: postData.id,
    client_id: postData.client_id,
    content: finalContent,
    topic_pillar: postData.topic_pillar,
    post_format: postData.post_format,
    decision: finalDecision,
    was_edited: approvalData.decision === 'edited',
    rejection_reason: approvalData.rejection_reason || null,
    scheduled_for: approvalData.scheduled_for || null
  }
}];

// Build response for approved post
// Queue worker will pick this up and publish at scheduled_for time
const approvedPost = $input.first().json;

return [{
  json: {
    status: 'ok',
    decision: 'approved',
    post_id: approvedPost.id,
    post_status: approvedPost.post_status,
    scheduled_for: approvedPost.scheduled_for,
    message: 'Post approved and scheduled for publishing. Queue worker will publish it at the scheduled time.'
  }
}];

// Build response for rejected post
const rejectedPost = $input.first().json;

return [{
  json: {
    status: 'ok',
    decision: 'rejected',
    post_id: rejectedPost.id,
    post_status: rejectedPost.post_status,
    message: 'Post rejected successfully. A new post will be generated in the next run.'
  }
}];
